package com.sribuilds.triage.model;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Index;
import jakarta.persistence.PrePersist;
import jakarta.persistence.Table;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Getter;
import lombok.NoArgsConstructor;
import lombok.Setter;

import java.time.Instant;

/**
 * Durable audit record of every diagnostic report generated by the engine.
 *
 * <p>Redis is the fast deduplication cache; this table is the system of record
 * so that diagnostics survive cache eviction and can be re-inspected later.</p>
 */
@Entity
@Table(
        name = "incident_reports",
        indexes = {
                @Index(name = "idx_incident_error_hash", columnList = "error_hash"),
                @Index(name = "idx_incident_service_env", columnList = "service_name, environment")
        }
)
@Getter
@Setter
@Builder
@NoArgsConstructor
@AllArgsConstructor
public class IncidentReportEntity {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "incident_id", nullable = false, unique = true, length = 36)
    private String incidentId;

    @Column(name = "error_hash", nullable = false, length = 32)
    private String errorHash;

    @Column(name = "service_name", nullable = false, length = 200)
    private String serviceName;

    @Column(name = "environment", nullable = false, length = 32)
    private String environment;

    @Column(name = "root_cause", nullable = false, columnDefinition = "TEXT")
    private String rootCause;

    @Column(name = "severity", nullable = false, length = 16)
    private String severity;

    /** JSON array of recommended remediation steps. */
    @Column(name = "recommended_action", columnDefinition = "TEXT")
    private String recommendedAction;

    @Column(name = "suggested_fix_snippet", columnDefinition = "TEXT")
    private String suggestedFixSnippet;

    @Column(name = "created_at", nullable = false, updatable = false)
    private Instant createdAt;

    @PrePersist
    void onCreate() {
        this.createdAt = Instant.now();
    }
}
